shell_commands:
node -e "
const p=require('./package.json');
console.log('deps ajv:', p.dependencies && p.dependencies.ajv, '| devDeps ajv:', p.devDependencies && p.devDependencies.ajv);
console.log('version:', p.version);
" && ls node_modules/ajv/dist/ 2>/dev/null | head && node -e "console.log(require('./node_modules/ajv/package.json').types || require('./node_modules/ajv/package.json').typings)"

find node_modules -maxdepth 4 -name "ajv" -type d 2>/dev/null | head; echo "=== lock ajv entries ==="; node -e "
const lock=require('./package-lock.json');
for (const [k,v] of Object.entries(lock.packages||{})) {
  if (k.includes('ajv') || (k.includes('@types/ajv'))) console.log(k, '=>', v.version);
}
" | head -20

git fetch origin main 2>&1 | tail -2; git show origin/main:package-lock.json > /tmp/main-lock.json 2>/dev/null && node -e "
const lock=require('/tmp/main-lock.json');
for (const [k,v] of Object.entries(lock.packages||{})) {
  if (k === 'node_modules/ajv' || k.includes('@types/ajv') || k === 'node_modules/ajv-keywords' || k === 'node_modules/ajv-formats') console.log(k, '=>', v.version);
}
console.log('--- main package.json ajv dep:');
" && git show origin/main:package.json | grep -n '"ajv"'

node -e "
const lock=require('./package-lock.json');
console.log('lockfileVersion:', lock.lockfileVersion);
console.log('--- legacy dependencies section, ajv entries:');
for (const [k,v] of Object.entries(lock.dependencies||{})) {
  if (k.includes('ajv')) console.log(' ', k, '=>', v.version, v.dev ? '(dev)' : '');
}
console.log('--- root deps requiring ajv:');
console.log('  packages[\"\"].dependencies.ajv =', (lock.packages||{})[''].dependencies.ajv);
console.log('--- eslint requires:');
console.log('  eslint deps ajv =', (lock.packages||{})['node_modules/eslint']?.dependencies?.ajv);
"

mkdir -p /tmp/ajv-probe && cd /tmp/ajv-probe && cat > probe.ts <<'EOF'
import Ajv from 'ajv';
const ajv = new Ajv({strict: false, validateFormats: false});
console.log(typeof ajv.compile);
EOF
cat > tsconfig.json <<'EOF'
{
  "compilerOptions": {
    "target": "ES2022",
    "module": "NodeNext",
    "moduleResolution": "NodeNext",
    "lib": ["ES2022"],
    "strict": true,
    "esModuleInterop": true,
    "skipLibCheck": true,
    "isolatedModules": true,
    "noEmit": true,
    "typeRoots": ["/var/tmp/loop-bench/runs/02e68b283c3a/workspace/target/node_modules/@types"],
    "paths": { "ajv": ["/var/tmp/loop-bench/runs/02e68b283c3a/workspace/target/node_modules/ajv/dist/ajv.d.ts"] }
  },
  "files": ["probe.ts"]
}
EOF
timeout 120 node /var/tmp/loop-bench/runs/02e68b283c3a/workspace/target/node_modules/typescript/bin/tsc -p . 2>&1 | head -10; echo "exit: $?"

cd /tmp/v6-probe && node -e "
const fs=require('fs');
const t=JSON.parse(fs.readFileSync('tsconfig.json','utf8'));
t.compilerOptions.types=['node'];
t.compilerOptions.typeRoots=['/var/tmp/loop-bench/runs/02e68b283c3a/workspace/target/node_modules/@types'];
fs.writeFileSync('tsconfig.json', JSON.stringify(t,null,2));
" && /var/tmp/loop-bench/runs/02e68b283c3a/workspace/target/node_modules/.bin/tsc -p . 2>&1 | head -12; echo "v6-typings probe exit: ${pipestatus[1]:-$?}"
